/* trmm.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "trmm.h"

#ifdef _OPENMP
# include <omp.h>
/* Convenience macros so the code compiles cleanly with or without OpenMP. */
# define OMP_PARALLEL_FOR _Pragma("omp parallel for schedule(static)")
# define OMP_SIMD         _Pragma("omp simd")
#else
# define OMP_PARALLEL_FOR
# define OMP_SIMD
#endif

/* Tuneable block size along the column (j) dimension, used to improve
 * cache reuse for rows of B during the main kernel. */
#ifndef TRMM_J_BLOCK
# define TRMM_J_BLOCK 64
#endif


/* Array initialization. */
static
void init_array(int m, int n,
		DATA_TYPE *alpha,
		DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j;

  *alpha = (DATA_TYPE)1.5;

  /* Precompute reciprocals to replace divisions with cheaper
     multiplications inside the loops. */
  const DATA_TYPE inv_m = ((DATA_TYPE)1.0) / (DATA_TYPE)m;
  const DATA_TYPE inv_n = ((DATA_TYPE)1.0) / (DATA_TYPE)n;

  for (i = 0; i < m; i++) {
    for (j = 0; j < i; j++) {
      A[i][j] = (DATA_TYPE)((i + j) % m) * inv_m;
    }
    A[i][i] = (DATA_TYPE)1.0;
    for (j = 0; j < n; j++) {
      B[i][j] = (DATA_TYPE)((n + (i - j)) % n) * inv_n;
    }
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("B");
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
	if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, B[i][j]);
    }
  POLYBENCH_DUMP_END("B");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_trmm[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

  /* m and n are only used indirectly via the PolyBench loop bounds. */
  (void)m;
  (void)n;

//BLAS parameters
//SIDE   = 'L'
//UPLO   = 'L'
//TRANSA = 'T'
//DIAG   = 'U'
// => Form  B := alpha*A**T*B.
// A is MxM
// B is MxN
#pragma scop
  /* Optimized triangular matrix-matrix multiplication.
   *
   * Original kernel (per PolyBench):
   *
   *   for (i = 0; i < M; i++)
   *     for (j = 0; j < N; j++) {
   *       for (k = i+1; k < M; k++)
   *         B[i][j] += A[k][i] * B[k][j];
   *       B[i][j] = alpha * B[i][j];
   *     }
   *
   * This computes: B[i][j] = alpha * (B_old[i][j] +
   *             sum_{k=i+1..M-1} A[k][i] * B_old[k][j]).
   *
   * Key observations:
   *   - For fixed (i,j), the sum is over k>i, and B[k][j] is always
   *     read *before* row k of B is updated, so the right-hand side
   *     always uses the original B (B_old).
   *   - Different columns j are completely independent.
   *
   * We reorganize the computation into a rank-1 update style:
   *
   *   for (k = 1; k < M; k++)
   *     for (i = 0; i < k; i++)
   *       for (j = 0; j < N; j++)
   *         B[i][j] += A[k][i] * B[k][j];
   *   for (i = 0; i < M; i++)
   *     for (j = 0; j < N; j++)
   *       B[i][j] *= alpha;
   *
   * For each fixed (i,j), this applies the same sequence of updates
   * in the same order of k as the original code, using B_old[k][j]
   * as multiplicands and then scaling once by alpha. The in-place
   * semantics and floating-point summation order per (i,j) are thus
   * preserved.
   *
   * Advantages of the reordered form:
   *   - The innermost loop walks along contiguous elements of B's rows
   *     (Bi and Bk), greatly improving cache locality for B.
   *   - A[k][i] is constant inside the innermost loop and accessed
   *     along contiguous memory in k's row of A.
   *   - The innermost loop is a simple AXPY, well-suited for SIMD
   *     vectorization.
   *   - Different column blocks can be processed in parallel.
   */

  const int Mdim = _PB_M;
  const int Ndim = _PB_N;

  /* Column blocking to improve cache reuse of rows B[i][*] and B[k][*].
   * Each block operates on a disjoint set of columns, enabling safe
   * parallelization over blocks. */
  const int J_BLOCK = TRMM_J_BLOCK;
  const int num_j_blocks = (Ndim + J_BLOCK - 1) / J_BLOCK;

  /* Parallelize over independent column blocks when OpenMP is available.
   * When OpenMP is disabled, OMP_PARALLEL_FOR expands to nothing and
   * the loop executes sequentially. */
  OMP_PARALLEL_FOR
  for (int blk = 0; blk < num_j_blocks; ++blk)
  {
    const int j_start = blk * J_BLOCK;
    const int j_end = (j_start + J_BLOCK < Ndim) ? (j_start + J_BLOCK) : Ndim;

    /* Main triangular update for this block of columns:
     * for all k>i, accumulate B[i][j] += A[k][i] * B[k][j]. */
    for (k = 1; k < Mdim; ++k) {
      DATA_TYPE *restrict Bk = &B[k][0];

      for (i = 0; i < k; ++i) {
        DATA_TYPE *restrict Bi = &B[i][0];
        DATA_TYPE a_ki = A[k][i];

        /* Inner loop over contiguous memory in j: this is the main
         * compute-intensive kernel and is vectorized when possible. */
        OMP_SIMD
        for (j = j_start; j < j_end; ++j) {
          Bi[j] += a_ki * Bk[j];
        }
      }
    }

    /* Scale the updated block of B by alpha: B[i][j] *= alpha.
     * Per-column semantics are identical to the original kernel
     * (scaling after all triangular updates for that column). */
    for (i = 0; i < Mdim; ++i) {
      DATA_TYPE *restrict Bi = &B[i][0];
      OMP_SIMD
      for (j = j_start; j < j_end; ++j) {
        Bi[j] *= alpha;
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,M,m,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n, &alpha, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_trmm (m, n, alpha, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(B)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
