#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "trmm.h"

/* Tunable blocking factor for the inner (column) dimension of B in the
 * main computational kernel. This controls the size of the contiguous
 * chunks of columns of B[i][*] and B[k][*] that are processed together.
 * It can be overridden at compile time, e.g.:
 *
 *   gcc -DTRMM_J_BLOCK=128 ...
 *
 * A value in the 32–256 range is usually reasonable for modern CPUs.
 */
#ifndef TRMM_J_BLOCK
# define TRMM_J_BLOCK 64
#endif


/* Array initialization.
 *
 * Optimizations:
 *  - Use local restrict-qualified pointers to make aliasing explicit.
 *  - Precompute 1/m and 1/n to avoid repeated floating-point divisions
 *    inside the loops.
 */
static
void init_array(int m, int n,
		DATA_TYPE *alpha,
		DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j;

  *alpha = 1.5;

  /* Local views with explicit row-major layout and restrict qualifier
     enable better optimization and vectorization. */
  DATA_TYPE (*restrict a)[m] = A;
  DATA_TYPE (*restrict b)[n] = B;

  const DATA_TYPE inv_m = (DATA_TYPE)1.0 / (DATA_TYPE)m;
  const DATA_TYPE inv_n = (DATA_TYPE)1.0 / (DATA_TYPE)n;

  for (i = 0; i < m; i++) {
    /* Initialize strictly lower-triangular part of A. */
    for (j = 0; j < i; j++) {
      a[i][j] = (DATA_TYPE)((i + j) % m) * inv_m;
    }
    /* Unit diagonal. */
    a[i][i] = (DATA_TYPE)1.0;

    /* Initialize B row i. */
    for (j = 0; j < n; j++) {
      b[i][j] = (DATA_TYPE)((n + (i - j)) % n) * inv_n;
    }
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("B");
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
      if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, B[i][j]);
    }
  POLYBENCH_DUMP_END("B");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Original BLAS-style operation:
     SIDE   = 'L'
     UPLO   = 'L'
     TRANSA = 'T'
     DIAG   = 'U'
     => Form B := alpha * A**T * B.

   A is MxM, unit lower triangular.
   B is MxN.

   Optimizations:
   - Exchange the order of the j and k loops so that the inner-most loop
     iterates over the column index j. This makes accesses to B[i][j]
     and B[k][j] contiguous in memory (row-major layout), which greatly
     improves cache locality and enables efficient SIMD vectorization.
   - Process B in column blocks of size TRMM_J_BLOCK to improve cache
     reuse for wide matrices (large N).
   - Use local restrict-qualified VLA pointers for A and B to help the
     compiler understand aliasing and layout.
   - Hoist alpha into a local constant to keep it in a register.
   - Use #pragma GCC ivdep to signal the absence of loop-carried
     dependencies along j and encourage vectorization.
   - The triangular dependency along i is strictly preserved: rows are
     still processed in increasing i, and rows k>i of B are never
     modified before they are used in the update of row i, preserving
     the original algorithm's semantics.
*/
static
void kernel_trmm[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k, jb;

  /* Local restrict-qualified views of the matrices.  The dimensions
     are expressed using the runtime sizes m and n, matching the
     POLYBENCH_2D declarations. */
  DATA_TYPE (*restrict a)[m] = A;
  DATA_TYPE (*restrict b)[n] = B;

  const DATA_TYPE alpha_local = alpha;

  /* Pre-compute the largest multiple of TRMM_J_BLOCK not exceeding _PB_N.
     This allows the main j-blocked loops to be free of bounds checks. */
  const int n_full = (_PB_N / TRMM_J_BLOCK) * TRMM_J_BLOCK;

  //BLAS parameters
  //SIDE   = 'L'
  //UPLO   = 'L'
  //TRANSA = 'T'
  //DIAG   = 'U'
  // => Form  B := alpha*A**T*B.
  // A is MxM
  // B is MxN
#pragma scop
  for (i = 0; i < _PB_M; i++)
  {
    /* Process full column blocks of width TRMM_J_BLOCK. */
    for (jb = 0; jb < n_full; jb += TRMM_J_BLOCK)
    {
      const int j_end = jb + TRMM_J_BLOCK; /* j_end <= _PB_N by construction */

      /* Accumulate contributions from rows k > i into row i, for the
         current block of columns [jb, j_end). Each iteration over k
         performs a rank-1 update on a contiguous segment of rows i and k. */
      for (k = i + 1; k < _PB_M; k++)
      {
        const DATA_TYPE aik = a[k][i];

        #pragma GCC ivdep
        for (j = jb; j < j_end; j++)
        {
          b[i][j] += aik * b[k][j];
        }
      }

      /* Scale the updated portion of row i by alpha. This is equivalent
         to scaling the entire row after all k-updates, but operating
         per block keeps the memory access pattern simple and local. */
      #pragma GCC ivdep
      for (j = jb; j < j_end; j++)
      {
        b[i][j] *= alpha_local;
      }
    }

    /* Handle any remaining columns if _PB_N is not a multiple of TRMM_J_BLOCK. */
    if (n_full < _PB_N)
    {
      /* Accumulate contributions for columns [n_full, _PB_N). */
      for (k = i + 1; k < _PB_M; k++)
      {
        const DATA_TYPE aik = a[k][i];

        #pragma GCC ivdep
        for (j = n_full; j < _PB_N; j++)
        {
          b[i][j] += aik * b[k][j];
        }
      }

      /* Scale the remaining part of row i. */
      #pragma GCC ivdep
      for (j = n_full; j < _PB_N; j++)
      {
        b[i][j] *= alpha_local;
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,M,m,m);
