   Can be overridden at compile time, e.g. -DTRMM_J_BLOCK=128. */
#ifndef TRMM_J_BLOCK
# define TRMM_J_BLOCK 64
#endif


/* Array initialization. */
static
void init_array(int m, int n,
		DATA_TYPE *alpha,
		DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
