    }
  POLYBENCH_DUMP_END("B");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_trmm[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  /* Dimensions as local constants for readability. */
  const int Mdim = m;
  const int Ndim = n;

  /* --------------------------------------------------------------------
   * Optional temporary copy of B.
   *
   * - Original computation is: B := alpha * A^T * B (A is unit lower).
   * - In-place, each B[i][j] depends on B[k][j] for k > i, so rows are
   *   not independent and we cannot parallelize over i without care.
   *
   * - If we copy B to Bcopy and only read from that copy, the
   *   dependencies are removed and each row of the output can be
   *   computed independently:
   *
   *     B_new[i][j] = alpha * ( Bcopy[i][j]
   *                       + sum_{k>i} A[k][i] * Bcopy[k][j] ).
   *
   * - Extra memory is m*n elements. The original program uses
   *   m*m (A) + m*n (B). To respect the "≤ 50% extra memory" rule,
   *   we only allocate the copy when n <= m, i.e., m*n <= m*m and
   *   thus m*n <= 0.5 * (m*m + m*n).
   * ------------------------------------------------------------------ */
  DATA_TYPE *restrict Bcopy = NULL;
  DATA_TYPE (*restrict Bc)[Ndim] = NULL;

  if (Mdim > 0 && Ndim > 0 && Ndim <= Mdim) {
    size_t totalB = (size_t)Mdim * (size_t)Ndim;
    Bcopy = (DATA_TYPE*) malloc(totalB * sizeof(DATA_TYPE));
    if (Bcopy != NULL) {
      Bc = (DATA_TYPE (*)[Ndim]) Bcopy;

      /* Copy original B into the temporary buffer (read-only thereafter). */
      for (int i = 0; i < Mdim; ++i) {
        memcpy(Bc[i], B[i], (size_t)Ndim * sizeof(DATA_TYPE));
      }
    }
  }

  const DATA_TYPE alpha_local = alpha;

//BLAS parameters
//SIDE   = 'L'
//UPLO   = 'L'
//TRANSA = 'T'
//DIAG   = 'U'
// => Form  B := alpha*A**T*B.
// A is MxM
// B is MxN
#pragma scop
  if (Bc != NULL) {
    /* ================================================================
     * Version using a read-only copy of B (Bc).
     *
     *  - All reads of B come from Bc, so there are no cross-row
     *    dependencies. Each output row i is fully independent and can
     *    be computed in parallel.
     *
     *  - Loop order for a given row i is:
     *        for k = i+1..M-1
     *          for j = 0..N-1
     *            B[i][j] += A[k][i] * Bc[k][j];
     *        for j = 0..N-1
     *          B[i][j] *= alpha;
     *
     *    This preserves, for each element B[i][j], the original order
     *    of accumulation over k while improving cache locality by
     *    iterating over j (row-major) in the innermost loop.
     * ================================================================ */
#pragma omp parallel for schedule(static)
    for (int i = 0; i < Mdim; ++i) {
      DATA_TYPE *restrict Bi = B[i];

      /* Start from the original row: Bi = Bc[i]. */
      memcpy(Bi, Bc[i], (size_t)Ndim * sizeof(DATA_TYPE));

      /* Accumulate contributions from rows k > i. */
      for (int k = i + 1; k < Mdim; ++k) {
        const DATA_TYPE aik = A[k][i];
        const DATA_TYPE *restrict Bk = Bc[k];

        /* Block the j-loop to improve cache/TLB behavior for large N. */
        for (int jb = 0; jb < Ndim; jb += TRMM_J_BLOCK) {
          int j_end = jb + TRMM_J_BLOCK;
          if (j_end > Ndim)
            j_end = Ndim;
          for (int j = jb; j < j_end; ++j) {
            Bi[j] += aik * Bk[j];
          }
        }
      }

      /* Scale the entire row by alpha. */
      for (int jb = 0; jb < Ndim; jb += TRMM_J_BLOCK) {
        int j_end = jb + TRMM_J_BLOCK;
        if (j_end > Ndim)
          j_end = Ndim;
        for (int j = jb; j < j_end; ++j) {
          Bi[j] *= alpha_local;
        }
      }
    }
  } else {
    /* ================================================================
     * Fallback in-place version (no extra buffer).
     *
     *  - We must keep the i-loop sequential because B[i][*] uses
     *    B[k][*] for k > i, and those rows must remain unmodified
     *    until all such uses are finished.
     *
     *  - Within a fixed i, we reorder the inner loops as (k, j):
     *
     *        for k = i+1..M-1
     *          for j = 0..N-1
     *            B[i][j] += A[k][i] * B[k][j];
     *        for j = 0..N-1
     *          B[i][j] *= alpha;
     *
     *    This preserves, for each element B[i][j], the exact sequence
     *    of updates over k compared to the original code, but accesses
     *    B and A in a row-major friendly manner (j is innermost),
     *    improving cache utilization and enabling vectorization.
     * ================================================================ */
    for (int i = 0; i < Mdim; ++i) {
      DATA_TYPE *restrict Bi = B[i];

      /* Accumulate contributions from yet-unmodified rows k > i. */
      for (int k = i + 1; k < Mdim; ++k) {
        const DATA_TYPE aik = A[k][i];
        const DATA_TYPE *restrict Bk = B[k];

        /* Block the j-loop as in the Bc version. */
        for (int jb = 0; jb < Ndim; jb += TRMM_J_BLOCK) {
          int j_end = jb + TRMM_J_BLOCK;
          if (j_end > Ndim)
            j_end = Ndim;
          for (int j = jb; j < j_end; ++j) {
            Bi[j] += aik * Bk[j];
          }
        }
      }

      /* Scale row i in place. */
      for (int jb = 0; jb < Ndim; jb += TRMM_J_BLOCK) {
        int j_end = jb + TRMM_J_BLOCK;
        if (j_end > Ndim)
          j_end = Ndim;
        for (int j = jb; j < j_end; ++j) {
          Bi[j] *= alpha_local;
        }
      }
    }
  }
#pragma endscop

  if (Bcopy != NULL) {
    free(Bcopy);
  }
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,M,m,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n, &alpha, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_trmm (m, n, alpha, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(B)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
