#include <polybench.h>

/* Include benchmark-specific header. */
#include "trmm.h"


/* Array initialization. */
static
void init_array(int m, int n,
		DATA_TYPE *alpha,
		DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j;

  *alpha = 1.5;

  /* Hoist the divisions out of the loops to avoid
     repeating integer->floating conversions and divides. */
  const DATA_TYPE inv_m = (DATA_TYPE)1.0 / (DATA_TYPE)m;
  const DATA_TYPE inv_n = (DATA_TYPE)1.0 / (DATA_TYPE)n;

  for (i = 0; i < m; i++) {
    for (j = 0; j < i; j++) {
      /* Original formula: (DATA_TYPE)((i+j) % m) / m */
      A[i][j] = (DATA_TYPE)((i + j) % m) * inv_m;
    }
    A[i][i] = 1.0;

    for (j = 0; j < n; j++) {
      /* Original formula: (DATA_TYPE)((n + (i-j)) % n) / n */
      B[i][j] = (DATA_TYPE)((n + (i - j)) % n) * inv_n;
    }
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("B");
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
	if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, B[i][j]);
    }
  POLYBENCH_DUMP_END("B");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_trmm[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  /* Create restrict-qualified views of the 2D arrays.
     This helps the compiler assume that A and B do not alias,
     improving vectorization and scheduling. */
  DATA_TYPE (*restrict A_)[m] = (DATA_TYPE (*)[m])A;
  DATA_TYPE (*restrict B_)[n] = (DATA_TYPE (*)[n])B;

  /* Use the PolyBench loop bounds (may be smaller than m/n for
     certain data set configurations). */
  const int mm = _PB_M;
  const int nn = _PB_N;

  const DATA_TYPE alpha_local = alpha;

  /* BLAS parameters
     SIDE   = 'L'
     UPLO   = 'L'
     TRANSA = 'T'
     DIAG   = 'U'
     => Form  B := alpha * A**T * B
     A is MxM (unit lower triangular)
     B is MxN
  */
#pragma scop

  /* Parallelization strategy:
     - The true loop-carried dependency is along i (rows of B):
         B[k][j] (k>i) is read while those rows are still unmodified,
         and row k is only scaled by alpha when i == k.
       Therefore, i must remain logically sequential.
     - For a fixed i, all columns j are independent:
         each (i,j) updates only B[i][j] and reads B[k][j] (k>i),
         so different j values do not interfere.
     - We exploit this by:
         * keeping i as the outer (sequential) loop;
         * parallelizing the j-loop inside a single persistent
           OpenMP parallel region;
         * keeping the original loop order in the body so the
           scalar semantics are unchanged.
     - The outer 'for (i ...)' is executed redundantly by all
       threads, but the 'omp for' worksharing on the inner j-loop
       and the implicit barrier at its end ensure that:
         * each (i,j) pair is executed exactly once by some thread;
         * all threads stay in lock-step on the current i value,
           preserving the original row-wise dependency structure.
     - When compiled without OpenMP support, all '#pragma omp'
       directives are ignored and the code falls back to the
       optimized sequential version.
  */
#pragma omp parallel default(shared)
  {
    int i, j, k;

    for (i = 0; i < mm; i++)
    {
      /* Distribute columns across threads for the current row i. */
#pragma omp for schedule(static)
      for (j = 0; j < nn; j++)
      {
        /* Keep the frequently-used element in a register to
           avoid repeated loads/stores of B_[i][j]. */
        DATA_TYPE bij = B_[i][j];

        /* Inner reduction over k. There are no loop-carried
           dependencies across k iterations on any memory
           location (only on the private accumulator 'bij'),
           so it is safe to vectorize. On compilers not
           supporting OpenMP SIMD, this pragma is ignored. */
#pragma omp simd reduction(+:bij)
        for (k = i + 1; k < mm; k++)
        {
          bij += A_[k][i] * B_[k][j];
        }

        B_[i][j] = alpha_local * bij;
      }
      /* Implicit barrier at the end of 'omp for' keeps all
         threads synchronized before advancing to the next i. */
    }
  }

#pragma endscop
}


